import {hazards,sources} from './data.js';
import {allCategories as cats,allGuides as guides,topics,regions,roles,times,supports,features,devicePanels} from './extras.js';
const root=document.querySelector('#cg-root');
const surveyEndpoint=(window.CG_API_ORIGIN||'')+'/api/survey';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem('cg:'+k))??f}catch{return f}};
const save=(k,v)=>{try{localStorage.setItem('cg:'+k,JSON.stringify(v))}catch{toast('Device storage is unavailable. Print your plan to keep a copy.')}};

const readingSizes={comfortable:'Comfortable',large:'Large',extra:'Extra large',maximum:'Maximum (2×)'};
const storedReadingSize=read('text-size','comfortable');
const readingSize=Object.hasOwn(readingSizes,storedReadingSize)?storedReadingSize:'comfortable';
document.documentElement.dataset.textSize=readingSize;
let saved=new Set(read('saved',[])),done=new Set(read('done',[])),plan=read('plan',{}),checked=new Set(read('checked',[])),selectedFeatures=new Set(read('features',[]));
let draft=read('survey',{answers:{},workshops:[],roles:[],times:[],supports:[],features:[],region:regions[0]});
let resultData=null,shortlist=new Set(read('shortlist',[])),currentRoute='',modalOpener=null;
const paths={home:'M3 10 12 3l9 7v10H3Z M9 20v-7h6v7',tools:'m14 6 4-4 4 4-4 4 M14 6 3 17v4h4L18 10 M3 3l6 6',drop:'M12 2C10 6 4 11 4 15a8 8 0 0 0 16 0c0-4-6-9-8-13Z',bolt:'m13 2-9 12h7l-1 8 10-13h-7Z',car:'m4 8 2-5h12l2 5 M2 9h20v9H2Z M5 18v3m14-3v3M5 13h2m10 0h2',fence:'M4 3v19m8-19v19m8-19v19M1 8h22M1 16h22',leaf:'M20 3C8 1 2 8 5 16c7 9 18-1 15-13ZM4 21 16 8',paw:'M6 14c-5 6 0 9 6 6 6 3 11 0 6-6-3-4-9-4-12 0ZM6 5c-3-2-4 5-1 6 3 1 4-5 1-6Zm6-3c-3 0-3 7 0 7s3-7 0-7Zm6 3c-3 1-2 7 1 6s2-8-1-6Z',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6Z m-5 9 3 3 7-7',key:'M14 4a6 6 0 1 1-3 11l-6 6H2v-3l6-6A6 6 0 0 1 14 4Zm2 3h.01',radio:'M3 8h18v13H3Z M6 8l12-6M7 12h10M7 16h2m4 0h4m-10 3h10',heart:'M12 21 3 12C-3 3 8 0 12 7c4-7 15-4 9 5Z',tank:'M4 6c0-5 16-5 16 0v12c0 5-16 5-16 0Zm0 0c0 5 16 5 16 0M4 12c0 5 16 5 16 0M7 21v3m10-3v3',fire:'M13 2c2 7 8 8 7 14-1 9-17 8-16-1 0-3 3-6 4-8 0 4 2 5 3 5 4-3 2-7 2-10Z',flood:'M1 16c4-4 6 4 10 0s6 4 12 0M1 21c4-4 6 4 10 0s6 4 12 0M4 13V7l8-5 8 5v6M10 12V8h4v4',wind:'M2 7h13c7 0 5-8 1-5M2 12h18c5 0 3 8-1 5M2 17h8c5 0 4 7 0 5',sun:'M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2M18 12a6 6 0 1 0-12 0 6 6 0 0 0 12 0Z',phone:'M6 2h12v20H6ZM10 18h4',pin:'M20 9c0 6-8 13-8 13S4 15 4 9a8 8 0 0 1 16 0ZM15 9a3 3 0 1 0-6 0 3 3 0 0 0 6 0Z',arrow:'M3 12h17m-6-6 6 6-6 6',search:'M17 10a7 7 0 1 0-14 0 7 7 0 0 0 14 0Zm-2 5 7 7',bookmark:'M6 3h12v19l-6-4-6 4Z',check:'m4 12 5 5L21 5',close:'m5 5 14 14M5 19 19 5',print:'M6 8V2h12v6M6 18H2V8h20v10h-4M6 14h12v8H6Z',list:'M8 5h14M8 12h14M8 19h14M2 5h1m-1 7h1m-1 7h1',people:'M9 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8ZM1 22v-5c0-7 16-7 16 0v5m1-18c6 0 6 7 1 8m1 2c4 1 3 5 3 8',external:'M14 2h8v8m0-8L11 13M9 3H3v18h18v-7',menu:'M3 5h18M3 12h18M3 19h18'};
const icon=(n,cl='')=>`<svg class="icon ${cl}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.leaf}"/></svg>`;
const link=(label,url)=>`<a class="source-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ${icon('external')}</a>`;
const btn=(label,href,cl='primary')=>`<a class="button ${cl}" href="${href}">${label} ${icon('arrow')}</a>`;
const sectionHead=(eyebrow,title,more='')=>`<div class="section-head"><div><p class="eyebrow">${eyebrow}</p><h2>${title}</h2></div>${more}</div>`;
const intro=(eyebrow,title,desc)=>`<div class="page-intro"><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p class="lead">${desc}</p></div>`;
function shell(){root.innerHTML=`<a class="skip" href="#main">Skip to content</a><div class="emergency-bar"><div class="wrap"><span>Made for NSW. Shared for stronger communities.</span><span>Immediate danger? <a href="tel:000">Call 000</a> <b>·</b> Storm / flood help <a href="tel:132500">132 500</a></span></div></div><aside class="readability-bar" aria-label="Reading options"><div class="wrap"><div class="reading-control"><label for="reading-size">Text size</label><select id="reading-size">${Object.entries(readingSizes).map(([value,label])=>`<option value="${value}" ${value===readingSize?'selected':''}>${label}</option>`).join('')}</select></div><p>Choose a size that’s comfortable for you.</p><span id="reading-status" class="sr-only" role="status" aria-live="polite"></span></div></aside><header><div class="wrap nav-wrap"><a class="brand" href="#home" aria-label="Common Ground home"><span class="brand-mark">${icon('sun')}</span><span>Common Ground<small>THE PRACTICAL SKILLS FIELD GUIDE</small></span></a><button class="menu-toggle icon-button" data-action="menu" aria-label="Open navigation" aria-expanded="false">${icon('menu')}</button><nav aria-label="Main navigation"><a href="#library">Skills library</a><a href="#emergencies">Be prepared</a><a href="#neighbours">Help a neighbour</a><a href="#warnings">Warnings & phones</a><a href="#survey" class="nav-survey">Skills survey ${icon('arrow')}</a></nav></div></header><main id="main" tabindex="-1"></main><footer><div class="wrap footer-top"><a class="brand" href="#home"><span class="brand-mark">${icon('sun')}</span><span>Common Ground<small>A LITTLE KNOW-HOW GOES A LONG WAY.</small></span></a><div><a href="#about">About & sources</a><a href="#plan">My plan</a><a href="#results">Workshop priorities</a></div></div><div class="wrap footer-bottom"><span>A NSW learning resource. Local warnings and emergency services take priority.</span><span>Prepared 12 November 2026 · <a href="#about">Use & privacy</a></span></div></footer><dialog id="guide-dialog" aria-labelledby="guide-title"></dialog><div id="toast" role="status" aria-live="polite"></div>`;}
function categoryCard(c){return `<a class="category-card" href="#library?category=${c.id}"><span class="category-icon">${icon(c.icon)}</span><div><h3>${c.name}</h3><p>${c.description}</p><small>${guides.filter(g=>g.category===c.id).length} practical guides</small></div>${icon('arrow','card-arrow')}</a>`;}
function guideCard(g){const c=cats.find(c=>c.id===g.category);return `<article class="guide-card"><div class="guide-top"><span class="tag">${icon(c.icon)} ${esc(c.name)}</span><button class="icon-button ${saved.has(g.id)?'is-saved':''}" data-save="${g.id}" aria-pressed="${saved.has(g.id)}" aria-label="${saved.has(g.id)?'Unsave':'Save'} ${esc(g.title)}">${icon('bookmark')}</button></div><button class="guide-open" data-guide="${g.id}"><h3>${esc(g.title)}</h3><p>${esc(g.steps[0])}</p></button><div class="guide-bottom"><span>${done.has(g.id)?'✓ Read & practised':g.level}</span><button data-guide="${g.id}" aria-label="Read ${esc(g.title)}">Read guide ${icon('arrow')}</button></div></article>`;}
function hazardTiles(){return `<div class="hazard-tiles">${hazards.slice(0,4).map((h,i)=>`<a href="#emergencies?hazard=${h.id}" class="hazard-tile ${h.color}"><span class="tile-no">0${i+1}</span>${icon(h.icon)}<h3>${h.short}</h3><span>Prepare. Respond. Recover. ${icon('arrow')}</span></a>`).join('')}</div>`;}
function home(){return `<section class="wrap hero"><div class="hero-copy"><p class="eyebrow"><span class="little-line"></span> FOR NSW HOMES & COUNTRY COMMUNITIES</p><h1>A little know-how.<br>A lot more<br><em>independence.</em></h1><p class="lead">The everyday skills nobody thought to teach you. From fixing a loose handle to preparing for a flood—start where you are, learn at your pace.</p><div class="button-row">${btn('Find your next skill','#library')}${btn('Be emergency ready','#emergencies','text-button')}</div><div class="hero-facts"><span><strong>${guides.length}</strong> useful skills</span><span><strong>${cats.length}</strong> areas of know-how</span><span><strong>NSW</strong> local guidance</span></div></div><figure class="hero-photo"><img src="./assets/workbench.png" alt="Gloves, hand tools and a green toolbox on a rural workbench overlooking a paddock" fetchpriority="high"/><span class="photo-label">COUNTRY KNOW-HOW.<br>EVERYDAY CONFIDENCE.</span><figcaption><span>${icon('leaf')} Good skills are worth passing on.</span><span>FIELD NOTES / 01</span></figcaption></figure></section><section class="wrap search-band"><div><span class="eyebrow">LET’S START WITH SOMETHING USEFUL</span><h2>What would you like to know?</h2></div><form id="home-search" role="search"><label class="sr-only" for="home-query">Search skills</label>${icon('search')}<input id="home-query" name="q" placeholder="Try “water tank”, “gate” or “phone alerts”"/><button class="icon-button" aria-label="Search skills">${icon('arrow')}</button></form></section><section class="wrap section"><div class="section-head"><div><p class="eyebrow">A PLACE TO BEGIN</p><h2>Useful skills. For real life.</h2><p>No assumed knowledge. No judgement. Just a clear next step.</p></div><a class="text-link" href="#library">Explore all ${cats.length} skill areas ${icon('arrow')}</a></div><div class="category-grid">${['home','tools','water','farm','property','neighbours'].map(id=>categoryCard(cats.find(c=>c.id===id))).join('')}</div></section><section class="weather-section"><div class="wrap section">${sectionHead('WHEN THE WEATHER HAS OTHER PLANS','A plan feels better than a guess.',`<a href="#emergencies" class="text-link">All emergency guides ${icon('arrow')}</a>`)}<p class="section-copy">Practical preparation for the four hazards that shape life in NSW. Know what to do before, during and after.</p>${hazardTiles()}<div class="weather-foot">${icon('radio')} Have more than one way to get a warning. <a href="#warnings">Set up your radio & phone ${icon('arrow')}</a></div></div></section><section class="wrap section neighbour-promo"><div class="neighbour-art" aria-hidden="true"><span>${icon('home')}</span><div>${icon('heart')}</div><span>${icon('home')}</span><small>GOOD NEIGHBOURS. SHARED KNOW-HOW.</small></div><div><p class="eyebrow">LOOKING OUT FOR EACH OTHER</p><h2>Start with the person.<br>Then the property.</h2><p>Support an older or disabled neighbour with the things they want help with—gates, tanks, paths, animals or an outage plan. Make it practical. Make it together.</p>${btn('Build a neighbour help plan','#neighbours','primary')}</div></section><section class="survey-promo"><div class="wrap"><div><p class="eyebrow">TURN KNOW-HOW INTO COMMUNITY ACTION</p><h2>“Do you know how to…?”</h2><p>A quick tick-box survey to find out what people want to learn—and help choose useful local workshops.</p></div>${btn('Have your say','#survey','light')}</div></section><section class="wrap section">${sectionHead('SMALL STEPS, REAL CONFIDENCE','Three good things to learn today.')}<div class="guide-grid">${['water-1','comms-2','farm-1'].map(id=>guideCard(guides.find(g=>g.id===id))).join('')}</div></section>`;}
function library(p){let cat=p.get('category')||'all',q=p.get('q')||'';return `<div class="wrap">${intro('YOUR PRACTICAL SKILLS LIBRARY','You can learn this.',`${guides.length} starter guides for the house, the property and the moments that call for a plan. Choose a topic or look for a specific task.`)}<div class="library-layout"><aside class="library-filters" aria-label="Skill areas"><h2>Explore by area</h2>${[{id:'all',name:'All skills',icon:'list'},{id:'saved',name:'My saved guides',icon:'bookmark'},...cats].map(c=>`<button class="filter ${cat===c.id?'active':''}" data-category="${c.id}" aria-pressed="${cat===c.id}">${icon(c.icon)}${esc(c.name)}<span>${c.id==='all'?guides.length:c.id==='saved'?saved.size:guides.filter(g=>g.category===c.id).length}</span></button>`).join('')}</aside><div><div class="library-search">${icon('search')}<label class="sr-only" for="library-query">Search all skill guides</label><input id="library-query" type="search" value="${esc(q)}" placeholder="What would you like to know how to do?"/></div><div id="library-results"></div></div></div></div>`;}
function filterLibrary(){const p=new URLSearchParams(location.hash.split('?')[1]);let cat=p.get('category')||'all';const input=document.querySelector('#library-query'),q=input?.value.toLowerCase().trim()||'';const aliases={'tank':'tank gravity rainwater','alerts':'warning hazards phone','elderly':'neighbour support','disabled':'neighbour mobility accessible'};const search=q.split(/\s+/);const items=guides.filter(g=>(cat==='all'||cat==='saved'&&saved.has(g.id)||cat===g.category)&&search.every(w=>[g.title,cats.find(c=>c.id===g.category).name,...g.steps,g.caution,(aliases[w]&&g.category==='neighbours'&&(w==='elderly'||w==='disabled')?w:'')].join(' ').toLowerCase().includes(w)));document.querySelector('#library-results').innerHTML=`<div class="results-count" role="status">${items.length} ${items.length===1?'guide':'guides'}${q?' matching your search':''}<span>Saved on this device ${icon('bookmark')}</span></div><div class="guide-grid library-cards">${items.length?items.map(guideCard).join(''):`<div class="empty"><h3>No guides found yet.</h3><p>Try a broader word such as “water”, “phone” or “gate”.</p><button class="button primary" data-action="clear-search">Clear search</button></div>`}</div>`;}
function emergencyPage(p){const h=hazards.find(x=>x.id===p.get('hazard'))||hazards[0],phase=p.get('phase')||'before';return `<div class="wrap">${intro('BE PREPARED · NSW','Know the plan. Practise it.', 'Broad preparation for NSW hazards, with official links for your situation. Read current local warnings: the correct action changes with conditions.')}<div class="emergency-contact"><strong>${icon('phone')} Immediate danger, fire, trapped or injured?</strong><a href="tel:000">Call 000</a><span>NSW SES storm / flood help</span><a href="tel:132500">132 500</a></div><div class="hazard-tabs" aria-label="Choose emergency scenario">${hazards.map(x=>`<a href="#emergencies?hazard=${x.id}" class="${x.id===h.id?'active':''}" ${x.id===h.id?'aria-current="true"':''}>${icon(x.icon)}${x.short}</a>`).join('')}</div><article class="hazard-guide ${h.color}"><div class="hazard-guide-top"><div><p class="eyebrow">NSW SCENARIO GUIDE</p><h2>${h.title}</h2><p>${h.intro}</p></div>${icon(h.icon)}</div><div class="urgent-note">${icon('shield')}<strong>${h.urgent}</strong></div><div class="phase-tabs" role="tablist" aria-label="When to act">${['before','during','after'].map((x,i)=>`<button role="tab" aria-selected="${x===phase}" data-phase="${x}" data-hazard="${h.id}"><span>0${i+1}</span>${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div><div class="phase-content" role="tabpanel"><h3>${{before:'Prepare before it happens',during:'Act on the current advice',after:'Recover carefully'}[phase]||'Prepare before it happens'}</h3><ol class="step-list">${(h[phase]||h.before).map(s=>`<li>${esc(s)}</li>`).join('')}</ol><div class="rural-note">${icon('fence')}<div><strong>On a country property</strong><p>${h.rural}</p></div></div><div class="sources"><h4>Go to the official advice</h4>${h.links.map(x=>link(...x)).join('')}</div></div></article><section class="section compact">${sectionHead('MAKE IT YOURS','A written plan is a useful start.',btn('Create my plan','#plan'))}<p>Include transport, animals, access needs, backup helpers and what you will do if communications fail.</p></section><div class="warning-levels"><h3>Understand the warning—then read the action.</h3><div><span class="level advice">Advice<small>Stay informed</small></span><span class="level watch">Watch and Act<small>Take protective action now</small></span><span class="level emergency">Emergency Warning<small>Immediate danger. Act now.</small></span></div><p>An Emergency Warning can tell you to evacuate or shelter because leaving is unsafe. ${link('NSW warning levels','https://www.nsw.gov.au/emergency/get-ready/know-warnings-to-stay-safe')}</p></div></div>`;}
function warnings(){return `<div class="wrap">${intro('GET WARNINGS · ASK FOR HELP','Stay connected. Have a backup.','Set up phones and radio before an emergency. These are preparation guides; this site does not monitor incidents or send live alerts.')}<div class="contact-grid">${[['000','Fire or life-threatening emergency','tel:000'],['132 500','NSW SES flood / storm emergency help','tel:132500'],['1800 679 737','NSW RFS information line · not emergency dispatch','tel:1800679737'],['131 444','Non-urgent police assistance','tel:131444']].map(([n,t,u])=>`<a href="${u}" class="contact-card"><small>${t}</small><strong>${n} ${icon('phone')}</strong></a>`).join('')}</div><div class="official-strip"><strong>Live official information</strong>${[['Hazards Near Me','https://www.nsw.gov.au/emergency/hazards-near-me-app'],['NSW SES warnings','https://www.ses.nsw.gov.au/'],['RFS incidents','https://www.rfs.nsw.gov.au/fire-information/fires-near-me'],['BOM warnings','https://www.bom.gov.au/weather-and-climate/warnings-and-alerts'],['Live Traffic NSW','https://www.livetraffic.com/']].map(x=>link(...x)).join('')}</div><section class="section compact">${sectionHead('SET IT UP IN A QUIET MOMENT','Your phone & radio checklist.',`<button class="button secondary" data-action="print">${icon('print')} Print this guide</button>`)}<p class="section-copy">Menu names and availability depend on your device and software. Review the current official instructions. Never place a test emergency call.</p><div class="device-grid">${devicePanels.map((d,i)=>`<article class="device-card"><div class="device-heading">${icon(d.icon)}<span>0${i+1}</span></div><h3>${d.title}</h3><ol>${d.steps.map(t=>`<li>${t}</li>`).join('')}</ol><div class="sources">${d.links.map(x=>link(...x)).join('')}</div><label class="check-row"><input type="checkbox" data-check="device-${i}" ${checked.has('device-'+i)?'checked':''}/> I’ve reviewed this setup</label></article>`).join('')}</div></section><div class="info-grid"><article class="note-box"><h3>Telephone warning messages</h3><p>Emergency Alert can send recorded landline calls and SMS for a warning area. Keep provider address details current. A switched-off phone, no reception or power loss can prevent delivery; NBN landlines may fail during an outage.</p>${link('NSW RFS telephone warnings','https://www.rfs.nsw.gov.au/plan-and-prepare/alert-levels/telephone-warnings')}</article><article class="note-box"><h3>Accessible emergency calls</h3><p>Ordinary SMS to 000 or 106 is not supported. 106 is the TTY emergency service. People who are Deaf, hard of hearing or have speech communication difficulty can prepare an official National Relay Service emergency option.</p>${link('NRS emergency options and SMS Relay','https://www.accesshub.gov.au/about-the-nrs/how-to-make-an-emergency-call-using-the-nrs')}</article><article class="note-box"><h3>UHF on country properties</h3><p>Learn the owner agreed channel and call signs. UHF CB emergency channels 5/35 do not guarantee rescue and are not a substitute for 000. Emergency services do not routinely monitor them.</p>${link('ACMA CB radio guidance','https://www.acma.gov.au/licences/citizen-band-radio-stations-class-licence')}</article><article class="note-box"><h3>Give a clear emergency report</h3><p>Say FIRE, POLICE or AMBULANCE; give the town, street address and correct gate. Explain what happened and who needs help, including access or communication needs. Stay on the line and follow the operator.</p>${link('How to call Triple Zero','https://www.infrastructure.gov.au/media-communications/phone/triple-zero/how-call-triple-zero-000')}</article></div><p class="small-note">Contact sources: ${link('NSW SES','https://www.ses.nsw.gov.au/contact-nsw-ses')} ${link('NSW RFS','https://www.rfs.nsw.gov.au/about-us/contact-us')} ${link('NSW Police','https://www.police.nsw.gov.au/contact_us')}</p></div>`;}
function neighbours(){return `<div class="wrap">${intro('GOOD NEIGHBOURS · PRACTICAL HELP','Ask first. Make a plan together.','Help an older or disabled neighbour with the tasks they choose. Their knowledge of their own home, property and support needs comes first.')}<div class="principle-strip"><span>${icon('heart')} Ask what help is wanted</span><span>${icon('key')} Agree access & privacy</span><span>${icon('people')} Have a backup helper</span></div><div class="section-head"><div><p class="eyebrow">A PROPERTY WALK-THROUGH</p><h2>What is on the property?</h2><p>Tick the relevant items together to build a useful conversation checklist.</p></div></div><div class="feature-grid">${features.map(f=>`<label class="feature ${selectedFeatures.has(f.id)?'selected':''}"><input type="checkbox" data-feature="${f.id}" ${selectedFeatures.has(f.id)?'checked':''}/>${icon(f.icon)}<strong>${f.name}</strong></label>`).join('')}</div><div id="property-tasks"></div><div class="info-grid section compact"><article class="note-box"><h3>A support plan, led by the person</h3><p>Agree preferred communication, warning access, check-ins, mobility aids, transport and an accessible destination. Ask before recording or sharing information.</p>${link('NSW SES inclusive planning','https://www.ses.nsw.gov.au/plan-and-prepare/community-service-providers')}${link('Person-Centred Emergency Preparedness','https://collaborating4inclusion.org/pcep/')}</article><article class="note-box"><h3>Equipment and personal assistance</h3><p>Let the person and their provider guide medical power backups and transfers. Arrange trained help for lifting, hoists or personal care. Life-support registration does not guarantee uninterrupted electricity.</p>${link('Life-support electricity guidance','https://www.energymadeeasy.gov.au/article/customers-using-life-support-equipment')}${link('People-handling guidance','https://www.safeworkaustralia.gov.au/book/health-care-and-social-assistance/hazards-risks-and-controls/hazardous-manual-tasks')}</article></div><div class="button-row">${btn('Write our agreed help plan','#plan')}${btn('Survey local training needs','#survey','secondary')}</div><section class="section">${sectionHead('LEARN TOGETHER','Skills for useful neighbour help.')}<div class="guide-grid">${guides.filter(g=>g.category==='neighbours').map(guideCard).join('')}</div></section></div>`;}
function propertyTasks(){const box=document.querySelector('#property-tasks');if(box)box.innerHTML=selectedFeatures.size?`<div class="property-checklist"><div class="section-head"><h3>Your agreed walk-through checklist</h3><button class="button secondary" data-action="print">${icon('print')} Print checklist</button></div><p class="small-note">A learning checklist, not an official inspection. Selections stay on this device.</p>${features.filter(f=>selectedFeatures.has(f.id)).map(f=>`<div class="property-task">${icon(f.icon)}<div><h4>${f.name}</h4><p>${f.task}</p></div><button class="text-link" data-guide="${f.guide}">Learn this ${icon('arrow')}</button></div>`).join('')}</div>`:`<div class="empty inline-empty">Choose a property feature above to see useful tasks and related guides.</div>`;}
const planFields=[['contact','Trusted contact & backup helper'],['communication','Preferred communication & no-response plan'],['radio','Local radio station & AM/FM frequency'],['trigger','Leave-early triggers & warning sources'],['destination','Accessible destination & backup'],['transport','Transport, mobility aids & equipment'],['animals','Animals: care, transport & destination'],['property','Water, gates, utilities & service contacts'],['support','Agreed neighbour tasks & review date']];
const kitItems=['Drinking water and suitable food','Medication, prescriptions and personal-care needs','Torch, battery radio and spare batteries','Charged devices, cables and power banks','First-aid kit and relevant training','Document copies, cash and spare keys','Suitable clothing, footwear and hygiene items','Mobility / communication aids and backup needs','Animal food, water, leads, carriers and records','Printed plan, local maps and contact numbers','Safe transport and an accessible destination','A backup helper and agreed check-in plan'];
function planPage(){return `<div class="wrap plan-page">${intro('YOUR OWN FIELD NOTES','A useful plan is one you can find.','Make a personal or agreed neighbour-help plan. It saves on this browser only. Print a copy for outages and share only with people the resident chooses.')}<div class="note-box privacy-note"><strong>${icon('key')} Keep private details private.</strong><p>Use the minimum information needed. Avoid gate codes, financial details or detailed medical information on a shared device. This plan is not sent to the survey database.</p></div><div class="plan-layout"><form id="plan-form"><div class="field"><label for="plan-title">Plan for</label><input id="plan-title" name="title" value="${esc(plan.title)}" placeholder="My home / an agreed neighbour support plan"/></div>${planFields.map(([id,label])=>`<div class="field"><label for="plan-${id}">${label}</label><textarea id="plan-${id}" name="${id}" rows="2">${esc(plan[id])}</textarea></div>`).join('')}<div class="button-row"><button type="button" class="button primary" data-action="print">${icon('print')} Print my plan</button><button type="button" class="button secondary" data-action="download-plan">Download text copy</button></div><p id="plan-status" class="small-note" role="status">Changes save as you type on this device.</p></form><aside class="kit-panel"><p class="eyebrow">PACK & CHECK</p><h2>Emergency essentials</h2><p>Adapt the kit to your household, support needs and likely isolation.</p>${kitItems.map((t,i)=>`<label class="check-row"><input type="checkbox" data-check="kit-${i}" ${checked.has('kit-'+i)?'checked':''}/>${t}</label>`).join('')}${link('NSW SES full kit guide','https://www.ses.nsw.gov.au/plan-and-prepare/emergency-kit')}<div class="plan-help"><strong>Life-threatening emergency: 000</strong><br>NSW SES storm / flood help: 132 500</div></aside></div></div>`;}
function headCalculator(){return `<section class="head-calculator"><div><p class="eyebrow">COUNTRY KNOW-HOW · LEARNING ESTIMATE</p><h3>Let gravity do some work.</h3><p>For water, each metre of vertical drop gives about 9.8 kPa of static pressure. Measure from the water surface to the outlet.</p><label for="head-height">Vertical drop: <strong id="head-value">5</strong> metres</label><input id="head-height" type="range" min="0" max="20" step="0.5" value="5"/><output id="head-output" for="head-height">≈ 49.0 kPa static pressure</output><p class="small-note">Flow, pipe losses, falling tank level and outlet requirements change performance. This estimate does not design a stand, size pipes or certify fire suppression.</p></div><div class="tank-diagram" aria-hidden="true"><div class="diagram-tank"><span>WATER SURFACE</span><div></div></div><div class="diagram-drop">↕<span>Vertical<br>head</span></div><div class="diagram-pipe"></div><span class="diagram-outlet">OUTLET</span></div></section>`;}
const multi=(name,opts,chosen)=>`<div class="choice-grid">${opts.map(o=>`<label class="choice"><input type="checkbox" name="${name}" value="${esc(o)}" ${chosen.includes(o)?'checked':''}/>${esc(o)}</label>`).join('')}</div>`;
function surveyPage(){if(read('submitted',null))return `<div class="wrap narrow">${intro('COMMUNITY SKILLS SURVEY','Your response has been received.','Thank you. Your anonymous answers will help identify useful local workshops. One response is accepted per saved response ID; counts are responses, not verified unique people.')}<div class="success-panel">${icon('check')}<h2>Good skills start with a conversation.</h2><p>Browse a guide, keep learning with a neighbour, or see the shared workshop priorities.</p><div class="button-row">${btn('See workshop priorities','#results')}${btn('Explore skills','#library','secondary')}</div></div></div>`;
return `<div class="wrap survey-page">${intro('A QUICK TICK & FLICK · COMMUNITY SKILLS SURVEY','Do you know how to…?','Tell us what you can do, what you want to learn and which workshops you would attend. There are no wrong answers. This is a self-assessment, not a competency test.')}<div class="survey-toolbar"><span>${icon('list')} 24 everyday questions</span><span>${icon('key')} No names or addresses</span><a href="#results">See workshop priorities ${icon('arrow')}</a></div><form id="survey-form"><fieldset class="survey-block"><legend><span>01</span> A little context <small>Optional</small></legend><div class="field"><label for="region">Broad NSW area</label><select id="region" name="region">${regions.map(r=>`<option ${r===draft.region?'selected':''}>${esc(r)}</option>`).join('')}</select></div><p class="field-label">I’m here as… (choose any)</p>${multi('roles',roles,draft.roles)}</fieldset><fieldset class="survey-block"><legend><span>02</span> Your skills & interests</legend><p>Tick one confidence level for every skill. “Not relevant” is a valid answer. Then choose up to <strong>three workshops</strong> you would attend.</p><div class="survey-progress"><span id="survey-progress-text">${Object.keys(draft.answers).length} of ${topics.length} answered</span><span id="workshop-progress">${draft.workshops.length} / 3 workshops selected</span></div><div class="survey-table"><div class="survey-row survey-table-head"><span>Do you know how to…</span><span>Confident</span><span>Some practice</span><span>Need to learn</span><span>Not relevant</span><span>Want a workshop</span></div>${topics.map((t,i)=>`<fieldset class="survey-row" id="question-${t.id}"><legend class="sr-only">Do you know how to ${esc(t.question)}</legend><div class="question-label"><small>${String(i+1).padStart(2,'0')} / ${t.group}</small><strong>${esc(t.question)}</strong></div>${[['confident','Confident'],['some','Some practice'],['need','Need to learn'],['na','Not relevant']].map(([v,label])=>`<label class="survey-answer"><input type="radio" name="q:${t.id}" value="${v}" aria-label="${esc(t.question)} ${label}" ${draft.answers[t.id]===v?'checked':''}/><span>${label}</span></label>`).join('')}<label class="survey-answer workshop-choice"><input type="checkbox" name="workshops" value="${t.id}" aria-label="Workshop: ${esc(t.question)}" ${draft.workshops.includes(t.id)?'checked':''}/><span>Want a workshop</span></label></fieldset>`).join('')}</div></fieldset><fieldset class="survey-block"><legend><span>03</span> Make workshops useful <small>Optional</small></legend><p class="field-label">Which times could work?</p>${multi('times',times,draft.times)}<p class="field-label">What would help you take part? No explanation needed.</p>${multi('supports',supports,draft.supports)}<p class="field-label">What is on the property you live on or help with?</p>${multi('features',features.map(f=>f.name),draft.features)}</fieldset><div class="survey-consent"><h3>How your answers are used</h3><p>Your tick-box answers are stored in the shared site database for workshop planning. Only summaries are shown here. We ask for no names, exact addresses, diagnoses or contact details. A random response ID prevents accidental duplicate submissions from this browser; it does not verify a unique person.</p><p>Your unfinished draft stays in this browser. You can clear it before submitting. Avoid submitting for someone else without their agreement.</p><label class="check-row"><input type="checkbox" id="survey-consent" required/> I agree my anonymous answers can be used to plan community workshops.</label><div id="survey-error" role="alert"></div><div class="button-row"><button class="button primary" id="survey-submit" type="submit">Submit my answers ${icon('arrow')}</button><button type="button" class="button secondary" data-action="clear-draft">Clear my draft</button></div></div></form></div>`;}
function resultPage(){return `<div class="wrap">${intro('FROM COMMUNITY ANSWERS TO USEFUL SESSIONS','What should we learn together?','A shared summary of submitted surveys. Rank workshop interest, compare confidence and make a local shortlist. These are self-reported responses, not proof of ability or a representative population survey.')}<div class="button-row no-print">${btn('Take the skills survey','#survey','secondary')}<button class="button secondary" data-action="refresh-results">Refresh results</button><button class="button secondary" data-action="export-results">Download summary CSV</button></div><div id="results-data" aria-live="polite"><div class="empty">Loading community responses…</div></div></div>`;}
async function loadResults(){const box=document.querySelector('#results-data');if(!box)return;box.innerHTML='<div class="empty">Loading community responses…</div>';try{const r=await fetch(surveyEndpoint,{cache:'no-store'});if(!r.ok)throw Error();resultData=await r.json();if(document.querySelector('#results-data'))renderResults();}catch{if(document.querySelector('#results-data'))box.innerHTML='<div class="empty"><h3>Results are unavailable right now.</h3><p>Please try again when you have a connection. No sample responses are shown.</p><button class="button primary" data-action="refresh-results">Try again</button></div>';}}
function ranked(){return topics.map(t=>({...t,...(resultData?.topics[t.id]||{confident:0,some:0,need:0,na:0,workshops:0})})).sort((a,b)=>b.workshops-a.workshops||b.need-a.need||b.some-a.some||a.id.localeCompare(b.id));}
function renderResults(){const d=resultData,box=document.querySelector('#results-data');if(!box||!d)return;const rows=ranked(),max=Math.max(1,...rows.map(r=>r.workshops));box.innerHTML=`<div class="results-metrics"><div><strong>${d.total}</strong><span>submitted responses</span></div><div><strong>${d.total?rows.filter(t=>t.workshops>0).length:0}</strong><span>topics with workshop interest</span></div><div><strong>${shortlist.size}</strong><span>topics on this device’s shortlist</span></div></div>${!d.total?`<div class="empty"><h3>The first workshop starts with a first response.</h3><p>No survey responses have been submitted yet. As people contribute, priorities will appear here.</p>${btn('Complete the survey','#survey')}</div>`:`<div class="results-explainer">Sorted by workshop requests, then “Need to learn”, then “Some practice”. Confidence counts include “Not relevant”; interest is a separate choice. Sample size: ${d.total} responses. Last refreshed: ${new Date().toLocaleString('en-AU')}.</div><div class="results-table"><div class="ranking-row ranking-head"><span>Workshop topic</span><span>Requests</span><span>Need to learn</span><span>Some practice</span><span>Confident</span><span>Not relevant</span><span>Shortlist</span></div>${rows.map((t,i)=>`<div class="ranking-row"><div><small>${String(i+1).padStart(2,'0')} / ${t.group}</small><strong>Know how to ${esc(t.question)}</strong><div class="bar-track"><div style="width:${t.workshops/max*100}%"></div></div></div><span data-label="Requests">${t.workshops}</span><span data-label="Need to learn">${t.need}</span><span data-label="Some practice">${t.some}</span><span data-label="Confident">${t.confident}</span><span data-label="Not relevant">${t.na}</span><label><input type="checkbox" data-shortlist="${t.id}" aria-label="Shortlist ${esc(t.question)}" ${shortlist.has(t.id)?'checked':''}/><span class="mobile-only">Shortlist</span></label></div>`).join('')}</div><div class="info-grid section compact">${[['Workshop times','times'],['Participation needs','supports'],['Property features','features'],['Broad NSW areas','regions']].map(([label,key])=>`<article class="note-box"><h3>${label}</h3>${Object.entries(d[key]).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="count-line"><span>${esc(k)}</span><strong>${v}</strong></div>`).join('')||'<p>No choices recorded.</p>'}</article>`).join('')}</div>`}<section class="shortlist-panel"><div class="section-head"><div><p class="eyebrow">FROM INTEREST TO ACTION</p><h2>Your workshop shortlist</h2></div><button class="button secondary" data-action="print">${icon('print')} Print shortlist</button></div><p>Saved on this device. Suggested session types are planning ideas; no workshops or trainers have been booked.</p>${topics.filter(t=>shortlist.has(t.id)).map(t=>`<div class="shortlist-item"><strong>Know how to ${esc(t.question)}</strong><p>${t.format}</p><button class="text-link" data-guide="${t.guide}">Read the starter guide ${icon('arrow')}</button></div>`).join('')||'<p class="small-note">Tick topics in the results table to make a shortlist.</p>'}</section>`;}
function about(){return `<div class="wrap narrow">${intro('ABOUT COMMON GROUND','Know-how belongs to everyone.','A practical NSW field guide for women learning independently, country newcomers, community helpers and anyone filling a gap in their skills.')}<div class="prose"><h2>Start where you are.</h2><p>Skills are learned, practised and passed on. This guide brings together everyday maintenance, farm resourcefulness, emergency preparation and person-led neighbour support. It makes no assumptions about a person’s ability based on gender, age or disability.</p><h2>How to use the guide</h2><p>There are ${guides.length} starter guides across ${cats.length} areas. They introduce tasks and safe decision points. Use the exact manufacturer instructions and suitable hands-on training for your equipment. Licensing and site requirements vary; use qualified trades where required.</p><h2>Emergency information</h2><p>The seven scenario guides cover common NSW preparation and recovery needs. They cannot cover every property, support need or changing incident. Current warnings and emergency-service directions take priority. In immediate danger, fire or a life-threatening emergency call 000; for NSW flood and storm emergency help call 132 500.</p><h2>Sources & currency</h2><p>Prepared on 12 November 2026 using official NSW, Australian Government, equipment-provider and inclusion resources linked throughout. Phone settings and services can change; check the linked current guidance. The resource is not endorsed by these organisations. Broader Australian sources are labelled where NSW-specific guidance is unavailable.</p><div class="sources">${[['NSW RFS','https://www.rfs.nsw.gov.au/plan-and-prepare'],['NSW SES','https://www.ses.nsw.gov.au/plan-and-prepare'],['Fire and Rescue NSW','https://www.fire.nsw.gov.au/'],['NSW Health','https://www.health.nsw.gov.au/'],['SafeWork NSW','https://www.safework.nsw.gov.au/'],['NSW farm water','https://www.nsw.gov.au/regional-and-primary-industries/agriculture/water/monitoring-planning'],['Person-Centred Emergency Preparedness','https://collaborating4inclusion.org/pcep/']].map(x=>link(...x)).join('')}</div><h2>Your information</h2><p>Saved guides, checklists, personal plans and survey drafts use this browser’s local storage. They are not synced across devices and can be lost if browser data is cleared. Do not store private access or medical details on a shared device.</p><p>Only an intentionally submitted survey goes into the shared database: confidence answers, workshop choices, optional broad area, roles, session times, participation needs and property features, plus a random response ID and submission time. The results page shows aggregate counts. The form asks for no names, exact addresses or contact information. It uses no advertising trackers. Hosting services may process technical connection information under their own terms.</p><p>The survey form does not verify identities: counts are submitted responses, not verified unique people. Device-local duplicate protection limits accidental repeats. Use results with local consultation, accessible recruitment and qualified trainers.</p><h2>Photography</h2><p>The rural workbench image was created for this site with the built-in image generation tool. It illustrates the field-guide theme.</p><h2>Useful offline preparation</h2><p>Print emergency instructions, your radio frequency and your plan before an outage. The site and live warning links require internet; saved local data does not make the entire website available offline.</p></div></div>`;}
function openGuide(id){const g=guides.find(x=>x.id===id);if(!g)return;modalOpener=document.activeElement;const c=cats.find(c=>c.id===g.category),d=document.querySelector('#guide-dialog');d.innerHTML=`<div class="dialog-top"><span class="tag">${icon(c.icon)} ${c.name}</span><button class="icon-button" data-action="close-guide" aria-label="Close guide">${icon('close')}</button></div><p class="eyebrow">${g.level} · STARTER GUIDE</p><h2 id="guide-title">${esc(g.title)}</h2><div class="guide-tools"><strong>Have to hand</strong><p>${g.kit.map(esc).join(' · ')}</p></div><ol class="step-list">${g.steps.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><div class="caution">${icon('shield')}<div><strong>Know the limit</strong><p>${esc(g.caution)}</p></div></div>${g.id==='farm-1'?headCalculator():''}<label class="check-row"><input type="checkbox" data-done="${id}" ${done.has(id)?'checked':''}/> I’ve read this and practised the parts I can safely do.</label><div class="button-row"><button class="button secondary" data-save="${id}" aria-pressed="${saved.has(id)}">${icon('bookmark')} ${saved.has(id)?'Saved on this device':'Save guide'}</button><button class="button secondary" data-action="print">${icon('print')} Print guide</button></div><div class="sources"><p class="small-note">Use manufacturer instructions and appropriate training. This is a starter lesson, not a qualification.</p>${g.directSource?link('Further reading: official guidance',g.directSource):g.source&&sources[g.source]?link(...sources[g.source]):''}</div>`;d.showModal();document.body.classList.add('dialog-open');}
function closeGuide(){document.querySelector('#guide-dialog').close();document.body.classList.remove('dialog-open');modalOpener?.focus();}
function toast(t){const el=document.querySelector('#toast');if(!el)return;el.textContent=t;el.classList.add('visible');setTimeout(()=>el.classList.remove('visible'),3500);}
function download(name,content,type='text/plain'){const u=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function updateDraft(form){const fd=new FormData(form);draft.region=fd.get('region')||regions[0];for(const name of ['roles','times','supports','features','workshops'])draft[name]=fd.getAll(name);draft.answers=Object.fromEntries(topics.filter(t=>fd.get('q:'+t.id)).map(t=>[t.id,fd.get('q:'+t.id)]));save('survey',draft);document.querySelector('#survey-progress-text').textContent=`${Object.keys(draft.answers).length} of ${topics.length} answered`;document.querySelector('#workshop-progress').textContent=`${draft.workshops.length} / 3 workshops selected`;}
async function submitSurvey(form){updateDraft(form);const error=document.querySelector('#survey-error');error.textContent='';const missing=topics.find(t=>!draft.answers[t.id]);if(missing){error.textContent='Please choose a confidence level for every skill. “Not relevant” is fine.';const row=document.querySelector('#question-'+missing.id);row.classList.add('needs-answer');row.scrollIntoView({block:'center',behavior:'smooth'});row.querySelector('input').focus({preventScroll:true});return;}if(draft.workshops.length>3){error.textContent='Choose up to three workshop topics.';return;}if(!document.querySelector('#survey-consent').checked){error.textContent='Please agree to the workshop-planning use before submitting.';return;}const button=document.querySelector('#survey-submit');button.disabled=true;button.textContent='Submitting…';const id=read('response-id',null)||crypto.randomUUID();save('response-id',id);try{const r=await fetch(surveyEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,consent:true,...draft})});if(!r.ok)throw Error();save('submitted',{id,date:new Date().toISOString()});save('survey',{answers:{},workshops:[],roles:[],times:[],supports:[],features:[],region:regions[0]});route();window.scrollTo(0,0);}catch{error.textContent='Your answers were not confirmed. Your draft is saved here. Reconnect and try again; a retry will not add a duplicate response.';button.disabled=false;button.innerHTML='Try submitting again '+icon('arrow');}}
function route(){const [name,query='']=(location.hash.slice(1)||'home').split('?'),p=new URLSearchParams(query);currentRoute=name;const main=document.querySelector('#main');main.innerHTML=({home:()=>home(),library:()=>library(p),emergencies:()=>emergencyPage(p),warnings,neighbours,plan:planPage,survey:surveyPage,results:resultPage,about}[name]||home)();document.title=({'home':'Practical skills for everyday confidence','library':'Skills library','emergencies':'NSW emergency guides','neighbours':'Help a neighbour','warnings':'Radio, phone & emergency contacts','plan':'My preparedness plan','survey':'Do you know how to…?','results':'Workshop priorities','about':'About & sources'}[name]||'Field guide')+' | Common Ground';document.querySelectorAll('nav a').forEach(a=>{const active=a.hash.slice(1)===name;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.querySelector('nav').classList.remove('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false');if(name==='library'){filterLibrary();if(p.get('category')==='farm')document.querySelector('#library-results').insertAdjacentHTML('beforeend',headCalculator())}if(name==='neighbours')propertyTasks();if(name==='results')loadResults();}
shell();route();
window.addEventListener('hashchange',()=>{if(document.querySelector('#guide-dialog').open)closeGuide();route();window.scrollTo(0,0)});
document.addEventListener('submit',e=>{if(e.target.id==='home-search'){e.preventDefault();location.hash='library?q='+encodeURIComponent(new FormData(e.target).get('q'))}if(e.target.id==='survey-form'){e.preventDefault();submitSurvey(e.target)}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='library-query')filterLibrary();if(t.closest('#plan-form')){plan=Object.fromEntries(new FormData(t.closest('form')));save('plan',plan);document.querySelector('#plan-status').textContent='Saved on this device.';}if(t.id==='head-height'){const scope=t.closest('.head-calculator');scope.querySelector('#head-value').textContent=t.value;scope.querySelector('#head-output').textContent=`≈ ${(Number(t.value)*9.8).toFixed(1)} kPa static pressure`;}});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.check){t.checked?checked.add(t.dataset.check):checked.delete(t.dataset.check);save('checked',[...checked])}if(t.dataset.done){t.checked?done.add(t.dataset.done):done.delete(t.dataset.done);save('done',[...done])}if(t.dataset.feature){t.checked?selectedFeatures.add(t.dataset.feature):selectedFeatures.delete(t.dataset.feature);save('features',[...selectedFeatures]);t.closest('label').classList.toggle('selected',t.checked);propertyTasks()}if(t.dataset.shortlist){t.checked?shortlist.add(t.dataset.shortlist):shortlist.delete(t.dataset.shortlist);save('shortlist',[...shortlist]);renderResults()}if(t.closest('#survey-form')){if(t.name==='workshops'&&t.checked&&draft.workshops.length>=3){t.checked=false;toast('Choose your top three workshop topics. Untick one to change it.')}t.closest('.needs-answer')?.classList.remove('needs-answer');updateDraft(t.closest('form'))}});
document.addEventListener('click',e=>{const t=e.target.closest('button,[data-save]');if(!t)return;if(t.dataset.guide)openGuide(t.dataset.guide);if(t.dataset.category)location.hash='library?category='+t.dataset.category;if(t.dataset.phase)location.hash=`emergencies?hazard=${t.dataset.hazard}&phase=${t.dataset.phase}`;if(t.dataset.save){const id=t.dataset.save;saved.has(id)?saved.delete(id):saved.add(id);save('saved',[...saved]);t.classList.toggle('is-saved',saved.has(id));t.setAttribute('aria-pressed',saved.has(id));if(t.closest('dialog'))t.innerHTML=icon('bookmark')+(saved.has(id)?' Saved on this device':' Save guide');else t.setAttribute('aria-label',(saved.has(id)?'Unsave ':'Save ')+guides.find(g=>g.id===id).title);toast(saved.has(id)?'Guide saved on this device.':'Guide removed from saved guides.');}
const a=t.dataset.action;if(a==='menu'){const nav=document.querySelector('nav');nav.classList.toggle('open');t.setAttribute('aria-expanded',nav.classList.contains('open'))}if(a==='close-guide')closeGuide();if(a==='clear-search'){document.querySelector('#library-query').value='';filterLibrary()}if(a==='print')window.print();if(a==='refresh-results')loadResults();if(a==='download-plan'){const text=['COMMON GROUND · NSW PREPAREDNESS PLAN',plan.title||'',...planFields.map(([id,l])=>l+'\n'+(plan[id]||'(not yet recorded)')),'EMERGENCY KIT',...kitItems.map((s,i)=>(checked.has('kit-'+i)?'[x] ':'[ ] ')+s),'000: life-threatening emergency / fire','NSW SES: 132 500'].join('\n\n');download('common-ground-plan.txt',text)}if(a==='clear-draft'){draft={answers:{},workshops:[],roles:[],times:[],supports:[],features:[],region:regions[0]};save('survey',draft);route();toast('Your unfinished draft has been cleared.')}if(a==='export-results'){if(!resultData){toast('Load the results before downloading.');return;}const lines=[['Topic','Workshop requests','Need to learn','Some practice','Confident','Not relevant','Shortlisted','Suggested session'],...ranked().map(t=>[t.question,t.workshops,t.need,t.some,t.confident,t.na,shortlist.has(t.id)?'Yes':'No',t.format]),[],['Submitted responses',resultData.total],['Counts are self-reported responses, not verified unique people.']];download('common-ground-workshop-summary.csv','\uFEFF'+lines.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n'),'text/csv;charset=utf-8')}});
document.querySelector('#guide-dialog').addEventListener('cancel',()=>document.body.classList.remove('dialog-open'));
document.addEventListener('click',e=>{if(e.target.closest('a.skip')){e.preventDefault();document.querySelector('#main').focus();document.querySelector('#main').scrollIntoView();}});
document.querySelector('#guide-dialog').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeGuide()}});

document.addEventListener('change',e=>{const field=e.target;if(field.id==='reading-size'&&Object.hasOwn(readingSizes,field.value)){document.documentElement.dataset.textSize=field.value;save('text-size',field.value);document.querySelector('#reading-status').textContent=readingSizes[field.value]+' text selected. Saved on this browser.';}});
